  function addCustomButtons() {
    if (document.querySelector(".custom-toolbar-button")) return true;

    const anchor = document.getElementById("print-button") 
                || document.getElementById("mdbook-print-button")
                || document.querySelector(".right-buttons")
                || document.querySelector(".left-buttons")
                || document.getElementById("menu-bar")
                || document.querySelector(".menu-bar");

    if (!anchor) return false;

    for (const btn of buttons) {
      const link = document.createElement("a");
      link.id = btn.id;
      link.className = "icon-button custom-toolbar-button";
      link.href = btn.url;
      link.target = "_blank";
      link.rel = "noopener noreferrer";
      link.title = btn.title;
      link.setAttribute("aria-label", btn.title);
      link.innerHTML = btn.svg;

      const svgEl = link.querySelector("svg");
      if (svgEl) {
        svgEl.setAttribute("aria-hidden", "true");
        svgEl.setAttribute("focusable", "false");
      }

      if (anchor.classList && (anchor.classList.contains("left-buttons") || anchor.classList.contains("right-buttons") || anchor.id === "menu-bar" || anchor.classList.contains("menu-bar"))) {
        anchor.appendChild(link);
      } else if (anchor.parentNode) {
        anchor.insertAdjacentElement("afterend", link);
      }
    }
    return true;
  }

  function cleanThemeMenu() {
    const themeButtons = document.querySelectorAll(".theme-popup button, [id*='theme-list'] button");
    if (!themeButtons.length) return false;

    const blocked = ["rust", "coal", "navy"];
    themeButtons.forEach(btn => {
      const label = btn.textContent.trim().toLowerCase();
      const id = (btn.id || "").toLowerCase();
      if (blocked.some(b => label === b || id.includes(b))) {
        const li = btn.closest("li");
        if (li) li.remove();
        else btn.remove();
      }
    });
    return true;
  }

  const interval = setInterval(() => {
    const bOk = addCustomButtons();
    const tOk = cleanThemeMenu();
    if (bOk && tOk) clearInterval(interval);
  }, 50);

  setTimeout(() => clearInterval(interval), 4000);
